
from rest_framework import serializers
from apps.catalog.models import Supplier

from decimal import Decimal
from rest_framework import serializers
from apps.catalog.models import Product, Supplier, Warehouse, Inventory, StockMovement

class SupplierSerializer(serializers.ModelSerializer):
    # Define which supplier fields the API accepts and returns.
    class Meta:
        model = Supplier
        fields = ["id", "name", "email", "phone", "address", "is_active", "created_at", "updated_at",]

        # These fields are generated by the server.
        read_only_fields = ["id", "created_at", "updated_at"]

class ProductSerializer(serializers.ModelSerializer):
    # Return supplier details as a readable name in the API response.
    supplier_name = serializers.CharField(
        source="supplier.name",
        read_only=True,
    )

    class Meta:
        model = Product
        fields = ["id", "sku", "name", "description", "supplier", "supplier_name", "cost_price", "selling_price", "is_active", "created_at", "updated_at",]
        # The database generates these fields.
        read_only_fields = ["id", "created_at", "updated_at"]

    def validate_sku(self, value):
        # Normalize SKU values so accidental surrounding spaces are removed.
        value = value.strip()

        if not value:
            raise serializers.ValidationError("SKU cannot be empty.")

        return value

    def validate(self, attrs):
        # Reject negative prices before saving the product.
        cost_price = attrs.get(
            "cost_price",
            getattr(self.instance, "cost_price", None),
        )
        selling_price = attrs.get(
            "selling_price",
            getattr(self.instance, "selling_price", None),
        )

        if cost_price is not None and cost_price < Decimal("0.00"):
            raise serializers.ValidationError({
                "cost_price": "Cost price cannot be negative."
            })

        if selling_price is not None and selling_price < Decimal("0.00"):
            raise serializers.ValidationError({
                "selling_price": "Selling price cannot be negative."
            })

        return attrs

class WarehouseSerializer(serializers.ModelSerializer):
    class Meta:
        model = Warehouse
        fields = ["id", "name", "code", "address", "is_active", "created_at", "updated_at"]
        read_only_fields = ["id", "created_at", "updated_at"]

    def validate_code(self, value):
        value = value.strip().upper()

        if not value:
            raise serializers.ValidationError("Warehouse code cannot be empty.")

        return value


class InventorySerializer(serializers.ModelSerializer):
    # Show the SKU without requiring a separate API request.
    product_sku = serializers.CharField(
        source="product.sku",
        read_only=True,
    )

    # Show the warehouse code in the response.
    warehouse_code = serializers.CharField(
        source="warehouse.code",
        read_only=True,
    )

    # Available stock is calculated by the server.
    available_quantity = serializers.SerializerMethodField()

    class Meta:
        model = Inventory
        fields = ["id", "product", "product_sku", "warehouse", "warehouse_code", "quantity", "reserved_quantity", "available_quantity", "created_at", "updated_at",]
        read_only_fields = [
            "id",
            "reserved_quantity",
            "created_at",
            "updated_at",
        ]

    def get_available_quantity(self, obj):
        # Reserved units cannot be sold again.
        return obj.quantity - obj.reserved_quantity

    def validate(self, attrs):
        # Prevent a stock record from being created for an inactive product.
        product = attrs.get(
            "product",
            getattr(self.instance, "product", None),
        )
        warehouse = attrs.get(
            "warehouse",
            getattr(self.instance, "warehouse", None),
        )

        if product and not product.is_active:
            raise serializers.ValidationError({
                "product": "Cannot add stock for an inactive product."
            })

        if warehouse and not warehouse.is_active:
            raise serializers.ValidationError({
                "warehouse": "Cannot add stock to an inactive warehouse."
            })

        return attrs

class StockMovementSerializer(serializers.ModelSerializer):
    # Display the product SKU in the API response.
    product_sku = serializers.CharField(
        source="product.sku",
        read_only=True,
    )

    # Display the warehouse code in the API response.
    warehouse_code = serializers.CharField(
        source="warehouse.code",
        read_only=True,
    )

    # Display the username of the user who created the movement.
    created_by_username = serializers.CharField(
        source="created_by.username",
        read_only=True,
    )

    class Meta:
        model = StockMovement
        fields = [
            "id",
            "product",
            "product_sku",
            "warehouse",
            "warehouse_code",
            "quantity",
            "movement_type",
            "reason",
            "created_by",
            "created_by_username",
            "created_at",
        ]

        # These fields are controlled by the server.
        read_only_fields = [
            "id",
            "created_by",
            "created_at",
        ]

    def validate(self, attrs):
        # A stock movement must always have a non-zero quantity.
        quantity = attrs.get("quantity")

        if quantity == 0:
            raise serializers.ValidationError({
                "quantity": "Quantity cannot be zero."
            })

        # Prevent movements for inactive products.
        product = attrs.get("product")

        if product and not product.is_active:
            raise serializers.ValidationError({
                "product": "Cannot create a movement for an inactive product."
            })

        # Prevent movements for inactive warehouses.
        warehouse = attrs.get("warehouse")

        if warehouse and not warehouse.is_active:
            raise serializers.ValidationError({
                "warehouse": "Cannot create a movement for an inactive warehouse."
            })

        return attrs
